const newS = Number(msg.payload);
const prevSoc = flow.get('prevSoc');
const oldS = msg.data && msg.data.old_state ? Number(msg.data.old_state.state) : (prevSoc != null ? Number(prevSoc) : NaN);
if (!isNaN(newS)) {
  flow.set('prevSoc', newS);
  flow.set('curSoc', newS);
  node.status({ text: '电量 ' + newS + '%', fill: 'green' });
}
if (isNaN(oldS) || isNaN(newS)) return null;
if (newS >= 90 && oldS < 90) {
  flow.set('swapSocBefore', oldS);
  node.status({ text: '换电 ' + oldS + '→' + newS + '%', fill: 'blue' });
  /* 回填：最近一条 node-red 记录的实际充后电量 */
  try {
    const fsx = global.get('fs');
    const dir = '/data/electric-log';
    const file = dir + '/records.jsonl';
    const lines = fsx.readFileSync(file, 'utf8').split('\n').filter(Boolean);
    if (lines.length) {
      const last = JSON.parse(lines[lines.length - 1]);
      const lastDate = Date.parse(last.date || '');
      if (lastDate && Date.now() - lastDate < 3 * 86400000 && last.socEnd === 100 && last.source === 'node-red') {
        last.socEnd = newS;
        last.full = newS >= 90;
        last.note = (last.note ? last.note + '；' : '') + '回填实际充后电量' + newS + '%';
        lines[lines.length - 1] = JSON.stringify(last);
        fsx.writeFileSync(file, lines.join('\n') + '\n');
      }
    }
  } catch (e) {}
  return [msg, { payload: { soc: oldS } }];
}
return null;

const fs = global.get('fs');
const dir = '/data/electric-log';
try { fs.mkdirSync(dir, { recursive: true }); } catch (e) {}
const p = {
  time: new Date().toISOString(),
  soc_before: flow.get('swapSocBefore'),
  mileage: Number(msg.payload) || null
};
fs.writeFileSync(dir + '/pending_swap.json', JSON.stringify(p, null, 2));
node.status({ text: '挂起: 前' + p.soc_before + '% 里程' + p.mileage, fill: 'blue' });
msg.payload = p;
return msg;

const fs = global.get('fs');
const WATT_SCALE = 1; // 功率实体单位：W=1；若为 kW 改 1000
const watts = Number(msg.payload) * WATT_SCALE;
if (isNaN(watts)) return null;
const dir = '/data/electric-log';
const file = dir + '/charging_session.json';
let s = null;
try { s = JSON.parse(fs.readFileSync(file, 'utf8')); } catch (err) {}
const now = Date.now();
if (watts > 8) {
  if (!s || !s.active) {
    s = { started: now, last_ts: now, kwh: 0, energy_start: null, soc_start_fallback: flow.get('curSoc') != null ? Number(flow.get('curSoc')) : null, mileage_fallback: flow.get('curMile') != null ? Number(flow.get('curMile')) : null, active: true };
    fs.writeFileSync(file, JSON.stringify(s));
    return [msg, null]; // 输出1：去读累计电量表，记录充电前读数
  }
  const dt = (now - s.last_ts) / 3600000;
  if (dt > 0 && dt < 24) s.kwh += watts / 1000 * dt;
  s.last_ts = now;
  delete s.candidateSince;
  fs.writeFileSync(file, JSON.stringify(s));
  node.status({ text: '充电中 ' + s.kwh.toFixed(3) + ' kWh', fill: 'green' });
  return null;
}
if (s && s.active) {
  const dt = (now - s.last_ts) / 3600000;
  if (dt > 0 && dt < 24) s.kwh += watts / 1000 * dt;
  s.last_ts = now;
  if (!s.candidateSince) s.candidateSince = now;
  fs.writeFileSync(file, JSON.stringify(s));
  node.status({ text: '低功率，确认结束中…', fill: 'yellow' });
  return [null, msg]; // 输出2：低功率，进入2分钟确认
}
node.status({ text: '等待充电（' + watts + 'W）', fill: 'grey' });
return null;

const fs = global.get('fs');
const WATT_SCALE = 1;
const watts = Number(msg.payload) * WATT_SCALE;
const dir = '/data/electric-log';
let s = null;
try { s = JSON.parse(fs.readFileSync(dir + '/charging_session.json', 'utf8')); } catch (e) {}
if (!s || !s.active) return null;
if (watts > 8) {
  s.candidateSince = null;
  fs.writeFileSync(dir + '/charging_session.json', JSON.stringify(s));
  node.status({ text: '继续充电', fill: 'green' });
  return null;
}
s.active = false;
fs.writeFileSync(dir + '/charging_session.json', JSON.stringify(s));
node.status({ text: '充电结束，计算度数…', fill: 'yellow' });
msg.charge = s;
return msg;

const fs = global.get('fs');
const dir = '/data/electric-log';
const PRICE = 0.65;
const LOW_KWH = 0.5;
const ENERGY_SCALE = 1; // kWh=1；Wh=0.001
let s = null;
try { s = JSON.parse(fs.readFileSync(dir + '/charging_session.json', 'utf8')); } catch (e) {}
let kwh = null;
if (s && s.energy_start != null) {
  const endVal = Number(msg.payload) * ENERGY_SCALE;
  if (!isNaN(endVal) && endVal >= s.energy_start) kwh = endVal - s.energy_start;
}
if (kwh == null && msg.charge && msg.charge.kwh != null) kwh = msg.charge.kwh; // 回退：功率积分
if (kwh == null) kwh = 0;
kwh = Math.round(kwh * 1000) / 1000;
if (kwh < LOW_KWH) {
  try { fs.unlinkSync(dir + '/charging_session.json'); } catch (e) {}
  node.status({ text: '忽略: ' + kwh + ' kWh < 0.5，疑似插座他用', fill: 'yellow' });
  return [null, { payload: { type: 'ignore', kwh: kwh } }];
}
let pending = null;
try { pending = JSON.parse(fs.readFileSync(dir + '/pending_swap.json', 'utf8')); } catch (e) {}
const sess = msg.charge || null;
const fallbackSocStart = sess && sess.soc_start_fallback != null ? Number(sess.soc_start_fallback) : null;
const now = new Date();
const pad = n => String(n).padStart(2, '0');
const rec = {
  id: 'nr-' + Date.now(),
  date: now.getFullYear() + '-' + pad(now.getMonth() + 1) + '-' + pad(now.getDate()),
  time: pad(now.getHours()) + ':' + pad(now.getMinutes()),
  mileage: pending && pending.mileage != null ? pending.mileage : (sess && sess.mileage_fallback != null ? sess.mileage_fallback : null),
  socStart: pending ? pending.soc_before : fallbackSocStart,
  socEnd: 100,
  energyKwh: kwh,
  cost: Math.round(kwh * PRICE * 100) / 100,
  price: PRICE,
  full: true,
  type: '家充',
  battery: '未知',
  note: (pending || fallbackSocStart != null) ? '' : '未检测到换电',
  source: 'node-red'
};
try { fs.mkdirSync(dir, { recursive: true }); } catch (e) {}
fs.appendFileSync(dir + '/records.jsonl', JSON.stringify(rec) + String.fromCharCode(10));
try { fs.unlinkSync(dir + '/pending_swap.json'); } catch (e) {}
try { fs.unlinkSync(dir + '/charging_session.json'); } catch (e) {}
node.status({ text: '已记录 ' + rec.energyKwh + ' kWh @ ' + rec.date, fill: 'green' });
msg.payload = rec;
return msg;

const TOKEN = '改成你的令牌';
if (!msg.req || !msg.req.query || msg.req.query.token !== TOKEN) {
  msg.statusCode = 403;
  msg.payload = { error: 'forbidden' };
  msg.headers = { 'Access-Control-Allow-Origin': '*', 'Content-Type': 'application/json', 'Cache-Control': 'no-store' };
  return msg;
}
const fs = global.get('fs');
const file = '/data/electric-log/records.jsonl';
let arr = [];
try {
  const lines = fs.readFileSync(file, 'utf8').split('\n').filter(Boolean);
  arr = lines.map(function (l) { try { return JSON.parse(l); } catch (e) { return null; } }).filter(Boolean);
} catch (e) {}
msg.payload = arr;
msg.headers = { 'Access-Control-Allow-Origin': '*', 'Content-Type': 'application/json', 'Cache-Control': 'no-store' };
return msg;

const TOKEN = '改成你的令牌';
if (!msg.req || !msg.req.query || msg.req.query.token !== TOKEN) {
  msg.statusCode = 403;
  msg.payload = { error: 'forbidden' };
  msg.headers = { 'Access-Control-Allow-Origin': '*', 'Content-Type': 'application/json', 'Cache-Control': 'no-store' };
  return msg;
}
const fs = global.get('fs');
const dir = '/data/electric-log';
const out = { pending: null, session: null, last: null, count: 0 };
try { out.pending = JSON.parse(fs.readFileSync(dir + '/pending_swap.json', 'utf8')); } catch (e) {}
try { out.session = JSON.parse(fs.readFileSync(dir + '/charging_session.json', 'utf8')); } catch (e) {}
try {
  const lines = fs.readFileSync(dir + '/records.jsonl', 'utf8').split('\n').filter(Boolean);
  out.count = lines.length;
  if (lines.length) {
    try { out.last = JSON.parse(lines[lines.length - 1]); } catch (e) {}
  }
} catch (e) {}
const tmpSoc = flow.get('curSoc');
out.soc = tmpSoc != null && tmpSoc !== '' ? Number(tmpSoc) : null;
out.mileage = flow.get('curMile') != null && flow.get('curMile') !== '' ? Number(flow.get('curMile')) : null;
/* 续航估算：容量×SOC÷平均墙端电耗（由集成侧统一计算） */
let range = null;
if (out.soc != null) {
  try {
    const fsx = global.get('fs');
    const lines = fsx.readFileSync('/data/electric-log/records.jsonl', 'utf8').split('\n').filter(Boolean);
    let totalKwh = 0;
    const mileSet = [];
    lines.forEach(function (l) {
      try {
        const r = JSON.parse(l);
        if (r.energyKwh != null) totalKwh += Number(r.energyKwh);
        if (r.mileage != null) mileSet.push(Number(r.mileage));
      } catch (e) {}
    });
    let totalKm = 0;
    if (mileSet.length >= 2) totalKm = Math.max.apply(null, mileSet) - Math.min.apply(null, mileSet);
    const wallWhKm = totalKm > 0 && totalKwh > 0 ? totalKwh * 1000 / totalKm : null;
    if (wallWhKm) range = Math.round(1863 * out.soc / 100 / wallWhKm);
  } catch (e) {}
}
out.range = range;
msg.payload = out;
msg.headers = { 'Access-Control-Allow-Origin': '*', 'Content-Type': 'application/json', 'Cache-Control': 'no-store' };
return msg;

const fs = global.get('fs');
const ENERGY_SCALE = 1; // 累计电量单位：kWh=1；若为 Wh 改 0.001
const val = Number(msg.payload);
const dir = '/data/electric-log';
const file = dir + '/charging_session.json';
let s = null;
try { s = JSON.parse(fs.readFileSync(file, 'utf8')); } catch (e) {}
if (s && s.active) {
  s.energy_start = isNaN(val) ? null : val * ENERGY_SCALE;
  fs.writeFileSync(file, JSON.stringify(s));
}
return null;

const TOKEN = '改成你的令牌';
if (!msg.req || !msg.req.query || msg.req.query.token !== TOKEN) {
  msg.statusCode = 403;
  msg.payload = { error: 'forbidden' };
  msg.headers = { 'Access-Control-Allow-Origin': '*', 'Content-Type': 'application/json', 'Cache-Control': 'no-store' };
  return msg;
}
const fsx = global.get('fs');
const dir = '/data/electric-log';
try { fsx.mkdirSync(dir, { recursive: true }); } catch (e) {}
const body = typeof msg.payload === 'string' ? msg.payload : JSON.stringify(msg.payload);
const nowD = new Date();
const localD = new Date(nowD.getTime() - nowD.getTimezoneOffset() * 60000);
const date = localD.toISOString().slice(0, 10);
const file = 'app_backup_' + date + '.json';
fsx.writeFileSync(dir + '/' + file, body);
msg.payload = { ok: true, file: file };
msg.headers = { 'Access-Control-Allow-Origin': '*', 'Content-Type': 'application/json', 'Cache-Control': 'no-store' };
return msg;

if (msg.payload && msg.payload.type === 'ignore') {
  msg.payload = { title: '电耗记账', message: '本次充电仅 ' + msg.payload.kwh + ' kWh，疑似插座他用，已忽略' };
} else if (msg.payload && msg.payload.energyKwh != null) {
  msg.payload = { title: '电耗记账', message: '充电完成：' + msg.payload.energyKwh + ' kWh，费用 ' + msg.payload.cost + ' 元' };
} else {
  msg.payload = { title: '电耗记账', message: '充电完成' };
}
return msg;

const v = Number(msg.payload);
if (!isNaN(v)) flow.set('curMile', v);
node.status({ text: '里程 ' + msg.payload + ' km', fill: 'grey' });
return null;
